import random
from sc2 import run_game, maps, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.constants import *
from sc2.position import Point2
from sc2.ids.buff_id import BuffId

class ProtossBot(sc2.BotAI):
    async def on_start(self):
        self.proxy_pylon_built = False
        self.proxy_pylon_position = None

    async def on_step(self, iteration):
        await self.distribute_workers()

        if not self.townhalls:
            if self.units(UnitTypeId.STALKER).exists:
                for stalker in self.units(UnitTypeId.STALKER).idle:
                    if self.enemy_units:
                        target = self.enemy_units.closest_to(stalker)
                        await self.do(stalker.attack(target))
                    else:
                        await self.do(stalker.attack(self.enemy_start_locations[0]))
            return

        await self.build_pylons()
        await self.train_probes()
        await self.build_assimilators()
        await self.build_gateway_and_cybercore()
        await self.research_warpgate()
        await self.morph_gateways()
        await self.warp_units()
        await self.build_proxy_pylon()
        await self.chrono_boost()
        await self.stalker_attack()

    async def build_pylons(self):
        if (
            self.supply_left < 5
            and self.already_pending(UnitTypeId.PYLON) == 0
            and self.can_afford(UnitTypeId.PYLON)
        ):
            nex = self.townhalls.ready.random
            pos = nex.position.towards(self.game_info.map_center, 5)
            await self.build(UnitTypeId.PYLON, near=pos)

    async def train_probes(self):
        for nexus in self.townhalls.ready.idle:
            if self.can_afford(UnitTypeId.PROBE) and self.workers.amount < self.townhalls.amount * 22:
                await self.do(nexus.train(UnitTypeId.PROBE))

    async def build_assimilators(self):
        for nexus in self.townhalls.ready:
            vgs = self.vespene_geyser.closer_than(15.0, nexus)
            for vg in vgs:
                if not self.gas_buildings.closer_than(1.0, vg).exists and self.can_afford(UnitTypeId.ASSIMILATOR):
                    worker = self.select_build_worker(vg.position)
                    if worker:
                        await self.do(worker.build(UnitTypeId.ASSIMILATOR, vg))

    async def build_gateway_and_cybercore(self):
        pylon = self.structures(UnitTypeId.PYLON).ready
        if not pylon.exists:
            return
        pylon = pylon.random

        if self.structures(UnitTypeId.GATEWAY).amount < 1 and self.can_afford(UnitTypeId.GATEWAY):
            await self.build(UnitTypeId.GATEWAY, near=pylon)

        if (
            self.structures(UnitTypeId.GATEWAY).ready.exists
            and self.structures(UnitTypeId.CYBERNETICSCORE).amount < 1
            and self.can_afford(UnitTypeId.CYBERNETICSCORE)
        ):
            await self.build(UnitTypeId.CYBERNETICSCORE, near=pylon)

        if (
            self.structures(UnitTypeId.CYBERNETICSCORE).ready.exists
            and self.structures(UnitTypeId.GATEWAY).amount < 3
            and self.can_afford(UnitTypeId.GATEWAY)
        ):
            await self.build(UnitTypeId.GATEWAY, near=pylon)

    async def research_warpgate(self):
        cybercore = self.structures(UnitTypeId.CYBERNETICSCORE).ready
        if cybercore.exists and not self.already_pending_upgrade(UpgradeId.WARPGATERESEARCH):
            if self.can_afford(RESEARCH_WARPGATE):
                await self.do(cybercore.first.research(UpgradeId.WARPGATERESEARCH))

    async def morph_gateways(self):
        if self.structures(UnitTypeId.CYBERNETICSCORE).ready.exists:
            if self.structures(UnitTypeId.CYBERNETICSCORE).ready.first.has_buff(BuffId.WARPGATERESEARCHING):
                return
            for gw in self.structures(UnitTypeId.GATEWAY).ready:
                abilities = await self.get_available_abilities(gw)
                if AbilityId.MORPH_WARPGATE in abilities:
                    await self.do(gw(AbilityId.MORPH_WARPGATE))

    async def warp_units(self):
        if not self.structures(UnitTypeId.WARPGATE).ready.exists:
            return
        if self.supply_left < 2:
            return
        if self.can_afford(UnitTypeId.STALKER):
            warpgate = self.structures(UnitTypeId.WARPGATE).ready.random
            pos = await self.find_placement(
                AbilityId.WARPGATETRAIN_STALKER,
                self.get_warpin_location(),
                placement_step=2
            )
            if pos:
                await self.do(warpgate.warp_in(UnitTypeId.STALKER, pos))

    def get_warpin_location(self):
        proxy = self.structures(UnitTypeId.PYLON).closer_than(30, self.enemy_start_locations[0])
        if proxy.exists:
            return proxy.random.position
        else:
            pylons = self.structures(UnitTypeId.PYLON).ready
            if pylons.exists:
                return pylons.random.position
            else:
                return self.start_location

    async def build_proxy_pylon(self):
        if self.proxy_pylon_built:
            return
        if self.structures(UnitTypeId.PYLON).amount < 2:
            return
        if self.can_afford(UnitTypeId.PYLON):
            pos = self.enemy_start_locations[0].towards(self.game_info.map_center, 20)
            placement = await self.find_placement(UnitTypeId.PYLON, pos, placement_step=4)
            if placement:
                await self.build(UnitTypeId.PYLON, near=placement)
                self.proxy_pylon_built = True
                self.proxy_pylon_position = placement

    async def chrono_boost(self):
        for nexus in self.townhalls.ready:
            if nexus.energy >= 50:
                if self.structures(UnitTypeId.CYBERNETICSCORE).ready.exists:
                    cyber = self.structures(UnitTypeId.CYBERNETICSCORE).ready.first
                    if not cyber.has_buff(BuffId.CHRONOBOOSTENERGYCOST):
                        await self.do(nexus(AbilityId.EFFECT_CHRONOBOOST, cyber))
                        continue
                if not nexus.has_buff(BuffId.CHRONOBOOSTENERGYCOST):
                    await self.do(nexus(AbilityId.EFFECT_CHRONOBOOST, nexus))

    async def stalker_attack(self):
        stalkers = self.units(UnitTypeId.STALKER).idle
        if stalkers.exists:
            if self.enemy_units.exists:
                for stalker in stalkers:
                    target = self.enemy_units.closest_to(stalker)
                    await self.do(stalker.attack(target))
            else:
                for stalker in stalkers:
                    await self.do(stalker.attack(self.enemy_start_locations[0]))

run_game(
